const rows = $input.all().map((i) => i.json);

function isRowDone(row) {
  const qa = String(row['QA Status'] || '').trim().toUpperCase();
  const score = Number(row['AI Score'] || 0);
  return (qa === 'PASS' || qa === 'PASS_NO_IMAGE') && score >= 90;
}

function getPrice(row) {
  const p = row['Price'] ?? row['Variant Price'] ?? null;
  if (p === null || p === undefined || String(p).trim() === '') return null;
  return p;
}

function normalizeRow(item) {
  const sku = String(item['SKU'] || item['Variant SKU'] || '').trim();
  const imageUrl = String(item['Product image URL'] || item['Image Src'] || item['Image URL'] || '').trim();
  const rawInfo = String(item['Description'] || item['Title'] || '').trim();
  let category = String(item['Product category'] || item['Type'] || '').trim();
  const vendor = item['Vendor'] || item['Brand'] || '';
  const price = getPrice(item);
  const rowNumber = item.row_number ?? item.__rowNumber ?? item.__row ?? null;

  if (category.startsWith('#') || /error/i.test(category)) {
    category = '';
  }

  return { sku, imageUrl, rawInfo, category, vendor, price, rowNumber, item };
}

// Trigger may send multiple rows (manual test). Pick first row that still needs QA.
let chosen = null;
const skipped = [];

for (const raw of rows) {
  if (isRowDone(raw)) {
    skipped.push({ sku: raw['SKU'] || '', reason: 'already PASS' });
    continue;
  }

  const r = normalizeRow(raw);

  if (!r.sku || !r.imageUrl || !r.rawInfo) {
    skipped.push({ sku: r.sku || '(no sku)', reason: 'incomplete row' });
    continue;
  }

  if (r.price === null) {
    skipped.push({ sku: r.sku, reason: 'no Price yet' });
    continue;
  }

  chosen = r;
  break;
}

if (!chosen) {
  return [];
}

return [{
  json: {
    ...chosen.item,
    row_number: chosen.rowNumber,
    processing_sku: chosen.sku,
    validated_image_url: chosen.imageUrl,
    validated_raw_info: chosen.rawInfo,
    validated_category: chosen.category,
    validated_vendor: chosen.vendor,
    validated_sku: chosen.sku,
    validated_price: chosen.price,
    validated_inventory: chosen.item['Inventory quantity'] || chosen.item['Variant Inventory Qty'] || chosen.item['Inventory Qty'] || null,
    _skipped_rows: skipped,
  },
}];

const inputItem = $input.first();
let payload = inputItem.json;

if (payload === undefined || payload === null) {
  payload = {};
} else if (typeof payload === 'string') {
  try {
    payload = JSON.parse(payload);
  } catch {
    payload = { text: payload };
  }
} else if (Array.isArray(payload)) {
  payload = { items: payload };
} else if (typeof payload !== 'object') {
  payload = { value: payload };
}

const photoroomBinary = $('Remove background Photoroom').first().binary;
if (!photoroomBinary?.data) {
  throw new Error('No image binary from Photoroom (Remove background Photoroom) — cannot upload to ImgBB');
}

// Pass n8n binary reference through — ImgBB multipart handles filesystem-v2 natively.
// Do NOT convert to base64 here (getBinaryDataBuffer fails on cross-node reads).
return [{
  json: payload,
  binary: photoroomBinary,
}];

